export function ContextWindow({
  usedPercent = {{usedPercent}},
  label = "{{label}}",
  accent = "{{accent}}",
  warnHigh = {{warnHigh}},
}) {
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430",
      background: "#FAF7F2", maxWidth: 360, padding: 16, borderRadius: 12, border: "1px solid #24143014", boxSizing: "border-box" }}>
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "baseline", marginBottom: 8 }}>
        <span style={{ fontWeight: 600, fontSize: 13 }}>{label}</span>
        <span style={{ fontSize: 13, color: "#24143099", fontVariantNumeric: "tabular-nums" }}>{usedPercent}%</span>
      </div>
      <div role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={usedPercent} aria-label={label}
        style={{ height: 10, borderRadius: 999, background: "#24143014", overflow: "hidden" }}>
        <div style={{ height: "100%", borderRadius: 999, background: accent, width: `${usedPercent}%`, transition: "width .2s ease" }} />
      </div>
      {warnHigh && (
        <p style={{ margin: "8px 0 0", fontSize: 12.5, color: "#241430", background: `color-mix(in srgb, #E8A020 22%, #FAF7F2)`,
          borderLeft: "3px solid #E8A020", padding: "6px 10px", borderRadius: 6, boxSizing: "border-box" }}>
          Nearing limit — consider summarising earlier turns.
        </p>
      )}
    </div>
  );
}
